    //WebSquare.wUnit.addCommand("pause", "500");
//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2_calendar_selectbox_hour').selectedIndex = 12");
    WebSquare.wUnit.addCommand("set", "mf_G_mf_gridView1__col2_calendar_selectbox_hour.selectedIndex = 12");
