//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2_calendar_selectbox_minute').selectedIndex = 32");
    WebSquare.wUnit.addCommand("set", "mf_G_mf_gridView1__col2_calendar_selectbox_minute.selectedIndex = 32");
    WebSquare.wUnit.addCommand("pause", "500");
//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2_calendar_selectbox_second').selectedIndex = 26");
