    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').innerText == '2015-12-24 12:32:26'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
